static char *vxstrfmt(const char *fmt, va_list ap) /* <=== vxstrfmt */ 
{
	char        *buf = NULL;
	char        *p   = NULL;
	size_t      len = (size_t) 0;
	char        tmp[LINEBUFSIZE];
	int         unprocessed = 0;
	int         long_long = 0;

	while (*fmt != '\0') {

		if ((p = (char *)strchr(fmt, '%')) == NULL) {
			/* no more format chars */
			xstrcat(buf, fmt);
			break;

		} else {        /* *p == '%' */
			/* take difference from fmt to just before `%' */
			len = (size_t) ((long)(p) - (long)fmt);
			/* append from fmt to p into buf if there's
			 * anythere there
			 */
			if (len > 0)
				xstrncat(buf, fmt, len);

			switch (*(++p)) {
		        case '%':	/* "%%" => "%" */
				xstrcatchar(buf, '%');
				break;

			case 'm':	/* "%m" => strerror(errno) */
				xslurm_strerrorcat(buf);
				break;

			case 't': 	/* "%t" => locally preferred date/time*/
				xstrftimecat(buf, "%x %X");
				break;
			case 'T': 	/* "%T" => "dd, Mon yyyy hh:mm:ss off" */
				xstrftimecat(buf, "%a, %d %b %Y %H:%M:%S %z");
				break;
			case 'M':
				if (!log)
					xiso8601timecat(buf, true);
				else {
					switch (log->fmt) {
					case LOG_FMT_ISO8601_MS: /* "%M" => "yyyy-mm-ddThh:mm:ss.fff"  */
						xiso8601timecat(buf, true);
						break;
					case LOG_FMT_ISO8601: /* "%M" => "yyyy-mm-ddThh:mm:ss.fff"  */
						xiso8601timecat(buf, false);
						break;
					case LOG_FMT_RFC5424_MS: /* "%M" => "yyyy-mm-ddThh:mm:ss.fff(+/-)hh:mm" */
						xrfc5424timecat(buf, true);
						break;
					case LOG_FMT_RFC5424:  /* "%M" => "yyyy-mm-ddThh:mm:ss.fff(+/-)hh:mm" */
						xrfc5424timecat(buf, false);
						break;
					case LOG_FMT_CLOCK:
						/* "%M" => "usec" */
#if defined(__FreeBSD__)
						snprintf(tmp, sizeof(tmp), "%d", clock());
#else
						snprintf(tmp, sizeof(tmp), "%ld", clock());
#endif
						xstrcat(buf, tmp);
						break;
					case LOG_FMT_SHORT: /* "%M" => "Mon DD hh:mm:ss"         */
						xstrftimecat(buf, "%b %d %T");
						break;
					case LOG_FMT_THREAD_ID:
						set_idbuf(tmp);
						xstrcat(buf, tmp);
						break;
					}
				}
				break;
			case 's':	/* "%s" => append string */
				/* we deal with this case for efficiency */
				if (unprocessed == 0)
					xstrcat(buf, va_arg(ap, char *));
				else
					xstrcat(buf, "%s");
				break;
			case 'f': 	/* "%f" => append double */
				/* again, we only handle this for efficiency */
				if (unprocessed == 0) {
					snprintf(tmp, sizeof(tmp), "%f",
						 va_arg(ap, double));
					xstrcat(buf, tmp);
				} else
					xstrcat(buf, "%f");
				break;
			case 'd':
				if (unprocessed == 0) {
					snprintf(tmp, sizeof(tmp), "%d",
						 va_arg(ap, int));
					xstrcat(buf, tmp);
				} else
					xstrcat(buf, "%d");
				break;
			case 'u':
				if (unprocessed == 0) {
					snprintf(tmp, sizeof(tmp), "%u",
						 va_arg(ap, int));
					xstrcat(buf, tmp);
				} else
					xstrcat(buf, "%u");
				break;
			case 'l':
				if ((unprocessed == 0) && (*(p+1) == 'l')) {
					long_long = 1;
					p++;
				}

				if ((unprocessed == 0) && (*(p+1) == 'u')) {
					if (long_long) {
						snprintf(tmp, sizeof(tmp),
							"%llu",
							 va_arg(ap,
								long long unsigned));
						long_long = 0;
					} else
						snprintf(tmp, sizeof(tmp),
							 "%lu",
							 va_arg(ap,
								long unsigned));
					xstrcat(buf, tmp);
					p++;
				} else if ((unprocessed==0) && (*(p+1)=='d')) {
					if (long_long) {
						snprintf(tmp, sizeof(tmp),
							"%lld",
							 va_arg(ap,
								long long int));
						long_long = 0;
					} else
						snprintf(tmp, sizeof(tmp),
							 "%ld",
							 va_arg(ap, long int));
					xstrcat(buf, tmp);
					p++;
				} else if ((unprocessed==0) && (*(p+1)=='f')) {
					if (long_long) {
						xstrcat(buf, "%llf");
						long_long = 0;
					} else
						snprintf(tmp, sizeof(tmp),
							 "%lf",
							 va_arg(ap, double));
					xstrcat(buf, tmp);
					p++;
				} else if ((unprocessed==0) && (*(p+1)=='x')) {
					if (long_long) {
						snprintf(tmp, sizeof(tmp),
							 "%llx",
							 va_arg(ap,
								long long int));
						long_long = 0;
					} else
						snprintf(tmp, sizeof(tmp),
							 "%lx",
							 va_arg(ap, long int));
					xstrcat(buf, tmp);
					p++;
				} else if (long_long) {
					xstrcat(buf, "%ll");
					long_long = 0;
				} else
					xstrcat(buf, "%l");
				break;
			case 'L':
				if ((unprocessed==0) && (*(p+1)=='f')) {
					snprintf(tmp, sizeof(tmp), "%Lf",
						 va_arg(ap, long double));
					xstrcat(buf, tmp);
					p++;
				} else
					xstrcat(buf, "%L");
				break;
			default:	/* try to handle the rest  */
				xstrcatchar(buf, '%');
				xstrcatchar(buf, *p);
				unprocessed++;
				break;
			}

		}

		fmt = p + 1;
	}

	if (unprocessed > 0) {
		vsnprintf(tmp, sizeof(tmp)-1, buf, ap);
		xfree(buf);
		return xstrdup(tmp);
	}

	return buf;
}

void slurm_xfree(void **item, const char *file, int line, const char *func) /* <=== slurm_xfree */ 
{
	if (*item != NULL) {
		size_t *p = (size_t *)*item - 2;
		/* magic cookie still there? */
		xmalloc_assert(p[0] == XMALLOC_MAGIC);
		p[0] = 0;	/* make sure xfree isn't called twice */
		free(p);
		*item = NULL;
	}
}

extern int container_g_create(uint32_t job_id) /* <=== container_g_create */ 
{
	int i, rc = SLURM_SUCCESS;

	if (job_container_init())
		return SLURM_ERROR;

	for (i = 0; ((i < g_container_context_num) && (rc == SLURM_SUCCESS));
	     i++) {
		rc = (*(ops[i].container_p_create))(job_id);
	}

	return rc;
}

void debug3(const char *fmt, ...) /* <=== debug3 */ 
{
	va_list ap;

	va_start(ap, fmt);
	log_msg(LOG_LEVEL_DEBUG3, fmt, ap);
	va_end(ap);
}

